import{_ as l,a0 as o,w as d,s as r,ao as i,I as p,x as n,a1 as t,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Python 函数式编程：不可变数据结构 | LCTT x X-CMD","titleTemplate":false,"description":"Python 函数式编程：不可变数据结构 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 函数式编程：不可变数据结构 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 函数式编程：不可变数据结构 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181004 Functional programming in Python- Immutable data structures","title":"Python 函数式编程：不可变数据结构","tag":"201811","desc":""},"relativePath":"201811/20181004 Functional programming in Python- Immutable data structures.md","filePath":"[post].md"}'),u={name:"201811/20181004 Functional programming in Python- Immutable data structures.md"};function c(g,s,h,b,k,f){const a=o("Link");return d(),r("div",null,[s[23]||(s[23]=i('<h1 id="python-函数式编程-不可变数据结构" tabindex="-1">Python 函数式编程：不可变数据结构 <a class="header-anchor" href="#python-函数式编程-不可变数据结构" aria-label="Permalink to “Python 函数式编程：不可变数据结构”">​</a></h1><blockquote><p>不可变性可以帮助我们更好地理解我们的代码。下面我将讲述如何在不牺牲性能的条件下来实现它。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/metrics_graph_stats_blue.png?itok=OKCc_60D" alt=""></p><p>在这个由两篇文章构成的系列中，我将讨论如何将函数式编程方法论中的思想引入至 Python 中，来充分发挥这两个领域的优势。</p><p>本文（也就是第一篇文章）中，我们将探讨不可变数据结构的优势。第二部分会探讨如何在 <code>toolz</code> 库的帮助下，用 Python 实现高层次的函数式编程理念。</p><p>为什么要用函数式编程？因为变化的东西更难推理。如果你已经确信变化会带来麻烦，那很棒。如果你还没有被说服，在文章结束时，你会明白这一点的。</p><p>我们从思考正方形和矩形开始。如果我们抛开实现细节，单从接口的角度考虑，正方形是矩形的子类吗？</p>',7)),p("p",null,[s[1]||(s[1]=n("子类的定义基于",-1)),t(a,{href:"https://en.wikipedia.org/wiki/Liskov_substitution_principle"},{default:e(()=>[...s[0]||(s[0]=[n("里氏替换原则",-1)])]),_:1}),s[2]||(s[2]=n("。一个子类必须能够完成超类所做的一切。",-1))]),s[24]||(s[24]=i(`<p>如何为矩形定义接口？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from zope.interface import Interface</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class IRectangle(Interface):</span></span>
<span class="line"><span>    def get_length(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;正方形能做到&quot;&quot;&quot;</span></span>
<span class="line"><span>    def get_width(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;正方形能做到&quot;&quot;&quot;</span></span>
<span class="line"><span>    def set_dimensions(self, length, width):</span></span>
<span class="line"><span>        &quot;&quot;&quot;啊哦&quot;&quot;&quot;</span></span></code></pre></div><p>如果我们这么定义，那正方形就不能成为矩形的子类：如果长度和宽度不等，它就无法对 <code>set_dimensions</code> 方法做出响应。</p><p>另一种方法，是选择将矩形做成不可变对象。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class IRectangle(Interface):</span></span>
<span class="line"><span>    def get_length(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;正方形能做到&quot;&quot;&quot;</span></span>
<span class="line"><span>    def get_width(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;正方形能做到&quot;&quot;&quot;</span></span>
<span class="line"><span>    def with_dimensions(self, length, width):</span></span>
<span class="line"><span>        &quot;&quot;&quot;返回一个新矩形&quot;&quot;&quot;</span></span></code></pre></div><p>现在，我们可以将正方形视为矩形了。在调用 <code>with_dimensions</code> 时，它可以返回一个新的矩形（它不一定是个正方形），但它本身并没有变，依然是一个正方形。</p><p>这似乎像是个学术问题 —— 直到我们认为正方形和矩形可以在某种意义上看做一个容器的侧面。在理解了这个例子以后，我们会处理更传统的容器，以解决更现实的案例。比如，考虑一下随机存取数组。</p><p>我们现在有 <code>ISquare</code> 和 <code>IRectangle</code>，而且 <code>ISequere</code> 是 <code>IRectangle</code> 的子类。</p><p>我们希望把矩形放进随机存取数组中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class IArrayOfRectangles(Interface):</span></span>
<span class="line"><span>    def get_element(self, i):</span></span>
<span class="line"><span>        &quot;&quot;&quot;返回一个矩形&quot;&quot;&quot;</span></span>
<span class="line"><span>    def set_element(self, i, rectangle):</span></span>
<span class="line"><span>        &quot;&quot;&quot;&#39;rectangle&#39; 可以是任意 IRectangle 对象&quot;&quot;&quot;</span></span></code></pre></div><p>我们同样希望把正方形放进随机存取数组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class IArrayOfSquare(Interface):</span></span>
<span class="line"><span>    def get_element(self, i):</span></span>
<span class="line"><span>        &quot;&quot;&quot;返回一个正方形&quot;&quot;&quot;</span></span>
<span class="line"><span>    def set_element(self, i, square):</span></span>
<span class="line"><span>        &quot;&quot;&quot;&#39;square&#39; 可以是任意 ISquare 对象&quot;&quot;&quot;</span></span></code></pre></div><p>尽管 <code>ISquare</code> 是 <code>IRectangle</code> 的子集，但没有任何一个数组可以同时实现 <code>IArrayOfSquare</code> 和 <code>IArrayOfRectangle</code>.</p><p>为什么不能呢？假设 <code>bucket</code> 实现了这两个类的功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rectangle = make_rectangle(3, 4)</span></span>
<span class="line"><span>&gt;&gt;&gt; bucket.set_element(0, rectangle) # 这是 IArrayOfRectangle 中的合法操作</span></span>
<span class="line"><span>&gt;&gt;&gt; thing = bucket.get_element(0) # IArrayOfSquare 要求 thing 必须是一个正方形</span></span>
<span class="line"><span>&gt;&gt;&gt; assert thing.height == thing.width</span></span>
<span class="line"><span>Traceback (most recent call last):</span></span>
<span class="line"><span>  File &quot;&lt;stdin&gt;&quot;, line 1, in &lt;module&gt;</span></span>
<span class="line"><span>AssertionError</span></span></code></pre></div><p>无法同时实现这两类功能，意味着这两个类无法构成继承关系，即使 <code>ISquare</code> 是 <code>IRectangle</code> 的子类。问题来自 <code>set_element</code> 方法：如果我们实现一个只读的数组，那 <code>IArrayOfSquare</code> 就可以是 <code>IArrayOfRectangle</code> 的子类了。</p><p>在可变的 <code>IRectangle</code> 和可变的 <code>IArrayOf*</code> 接口中，可变性都会使得对类型和子类的思考变得更加困难 —— 放弃变换的能力，意味着我们的直觉所希望的类型间关系能够成立了。</p><p>可变性还会带来作用域方面的影响。当一个共享对象被两个地方的代码改变时，这种问题就会发生。一个经典的例子是两个线程同时改变一个共享变量。不过在单线程程序中，即使在两个相距很远的地方共享一个变量，也是一件简单的事情。从 Python 语言的角度来思考，大多数对象都可以从很多位置来访问：比如在模块全局变量，或在一个堆栈跟踪中，或者以类属性来访问。</p><p>如果我们无法对共享做出约束，那我们可能要考虑对可变性来进行约束了。</p>`,19)),p("p",null,[s[4]||(s[4]=n("这是一个不可变的矩形，它利用了 ",-1)),t(a,{href:"https://www.attrs.org/en/stable/"},{default:e(()=>[...s[3]||(s[3]=[n("attr",-1)])]),_:1}),s[5]||(s[5]=n(" 库：",-1))]),s[25]||(s[25]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@attr.s(frozen=True)</span></span>
<span class="line"><span>class Rectange(object):</span></span>
<span class="line"><span>    length = attr.ib()</span></span>
<span class="line"><span>    width = attr.ib()</span></span>
<span class="line"><span>    @classmethod</span></span>
<span class="line"><span>    def with_dimensions(cls, length, width):</span></span>
<span class="line"><span>        return cls(length, width)</span></span></code></pre></div><p>这是一个正方形：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@attr.s(frozen=True)</span></span>
<span class="line"><span>class Square(object):</span></span>
<span class="line"><span>    side = attr.ib()</span></span>
<span class="line"><span>    @classmethod</span></span>
<span class="line"><span>    def with_dimensions(cls, length, width):</span></span>
<span class="line"><span>        return Rectangle(length, width)</span></span></code></pre></div><p>使用 <code>frozen</code> 参数，我们可以轻易地使 <code>attrs</code> 创建的类成为不可变类型。正确实现 <code>__setitem__</code> 方法的工作都交给别人完成了，对我们是不可见的。</p><p>修改对象仍然很容易；但是我们不可能改变它的本质。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>too_long = Rectangle(100, 4)</span></span>
<span class="line"><span>reasonable = attr.evolve(too_long, length=10)</span></span></code></pre></div>`,6)),p("p",null,[t(a,{href:"https://pyrsistent.readthedocs.io/en/latest/"},{default:e(()=>[...s[6]||(s[6]=[n("Pyrsistent",-1)])]),_:1}),s[7]||(s[7]=n(" 能让我们拥有不可变的容器。",-1))]),s[26]||(s[26]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 由整数构成的向量</span></span>
<span class="line"><span>a = pyrsistent.v(1, 2, 3)</span></span>
<span class="line"><span># 并非由整数构成的向量</span></span>
<span class="line"><span>b = a.set(1, &quot;hello&quot;)</span></span></code></pre></div><p>尽管 <code>b</code> 不是一个由整数构成的向量，但没有什么能够改变 <code>a</code> 只由整数构成的性质。</p><p>如果 <code>a</code> 有一百万个元素呢？<code>b</code> 会将其中的 999999 个元素复制一遍吗？<code>Pyrsistent</code> 具有“大 O”性能保证：所有操作的时间复杂度都是 <code>O(log n)</code>. 它还带有一个可选的 C 语言扩展，以在“大 O”性能之上进行提升。</p><p>修改嵌套对象时，会涉及到“变换器”的概念：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>blog = pyrsistent.m(</span></span>
<span class="line"><span>    title=&quot;My blog&quot;,</span></span>
<span class="line"><span>    links=pyrsistent.v(&quot;github&quot;, &quot;twitter&quot;),</span></span>
<span class="line"><span>    posts=pyrsistent.v(</span></span>
<span class="line"><span>        pyrsistent.m(title=&quot;no updates&quot;,</span></span>
<span class="line"><span>                     content=&quot;I&#39;m busy&quot;),</span></span>
<span class="line"><span>        pyrsistent.m(title=&quot;still no updates&quot;,</span></span>
<span class="line"><span>                     content=&quot;still busy&quot;)))</span></span>
<span class="line"><span>new_blog = blog.transform([&quot;posts&quot;, 1, &quot;content&quot;],</span></span>
<span class="line"><span>                          &quot;pretty busy&quot;)</span></span></code></pre></div><p><code>new_blog</code> 现在将是如下对象的不可变等价物：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{&#39;links&#39;: [&#39;github&#39;, &#39;twitter&#39;],</span></span>
<span class="line"><span> &#39;posts&#39;: [{&#39;content&#39;: &quot;I&#39;m busy&quot;,</span></span>
<span class="line"><span>            &#39;title&#39;: &#39;no updates&#39;},</span></span>
<span class="line"><span>           {&#39;content&#39;: &#39;pretty busy&#39;,</span></span>
<span class="line"><span>            &#39;title&#39;: &#39;still no updates&#39;}],</span></span>
<span class="line"><span> &#39;title&#39;: &#39;My blog&#39;}</span></span></code></pre></div><p>不过 <code>blog</code> 依然不变。这意味着任何拥有旧对象引用的人都没有受到影响：转换只会有局部效果。</p><p>当共享行为猖獗时，这会很有用。例如，函数的默认参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def silly_sum(a, b, extra=v(1, 2)):</span></span>
<span class="line"><span>    extra = extra.extend([a, b])</span></span>
<span class="line"><span>    return sum(extra)</span></span></code></pre></div><p>在本文中，我们了解了为什么不可变性有助于我们来思考我们的代码，以及如何在不带来过大性能负担的条件下实现它。下一篇，我们将学习如何借助不可变对象来实现强大的程序结构。</p><hr>`,12)),p("p",null,[s[9]||(s[9]=n("via: ",-1)),t(a,{href:"https://opensource.com/article/18/10/functional-programming-python-immutable-data-structures"},{default:e(()=>[...s[8]||(s[8]=[n("https://opensource.com/article/18/10/functional-programming-python-immutable-data-structures",-1)])]),_:1})]),p("p",null,[s[14]||(s[14]=n("作者：",-1)),t(a,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[10]||(s[10]=[n("Moshe Zadka",-1)])]),_:1}),s[15]||(s[15]=n(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[11]||(s[11]=[n("lujun9972",-1)])]),_:1}),s[16]||(s[16]=n(" 译者：",-1)),t(a,{href:"https://github.com/StdioA"},{default:e(()=>[...s[12]||(s[12]=[n("StdioA",-1)])]),_:1}),s[17]||(s[17]=n(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[13]||(s[13]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[20]||(s[20]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[18]||(s[18]=[n("LCTT",-1)])]),_:1}),s[21]||(s[21]=n(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...s[19]||(s[19]=[n("Linux中国",-1)])]),_:1}),s[22]||(s[22]=n(" 荣誉推出",-1))])])}const _=l(u,[["render",c]]);export{y as __pageData,_ as default};
